/* eslint-disable @typescript-eslint/no-unused-vars */
import { Contract } from 'ethers'

import {
  AddressLike,
} from '../interfaces'
import { toAddress } from '../utils'
import { StandardBridgeAdapter } from './standard-bridge'
import { hexStringEquals } from '../utils/hex-strings'
import { CrossChainMessenger } from '../cross-chain-messenger'
import { getContractInterface } from '../utils/contract-defs'
import { Console } from '../utils/console'

/**
 * Bridge adapter for the USDC bridge.
 */
export class USDCBridgeAdapter extends StandardBridgeAdapter {
  constructor(opts: {
    messenger: CrossChainMessenger
    l1Bridge: AddressLike
    l2Bridge: AddressLike
  }) {
    super(opts)

    this.messenger = opts.messenger

    // let l1BridgeName = 'L1GatewayRouter',
    //   l2BridgeName = 'L2GatewayRouter'
    let l1BridgeName = 'L1USDCGateway',
      l2BridgeName = 'L2USDCGateway'

    Console.log(
      'USDCBridgeAdapter',
      toAddress(
        opts.l1Bridge
      ),
      toAddress(
        opts.l2Bridge
      )
    )
    this.l1Bridge = new Contract(
      toAddress(
        opts.l1Bridge
      ),
      getContractInterface(l1BridgeName),
      this.messenger.l1Provider
    )
    this.l2Bridge = new Contract(
      toAddress(
        opts.l2Bridge
      ),
      getContractInterface(l2BridgeName),
      this.messenger.l2Provider
    )
  }

  public async supportsTokenPair(
    l1Token: AddressLike,
    l2Token: AddressLike
  ): Promise<boolean> {
    // Only support USDC deposits and withdrawals.
    Console.log('supportsTokenPair l1Token', toAddress(l1Token))
    Console.log(
      'supportsTokenPair this.messenger.contracts.l1.USDC.address',
      this.messenger.contracts.l1.USDC?.address
    )
    Console.log('supportsTokenPair l2Token', toAddress(l2Token))
    Console.log('supportsTokenPair L2USDC', this.messenger.contracts.l2?.L2USDC?.address)
    try {
      return (
        hexStringEquals(
          toAddress(l1Token),
          this.messenger.contracts.l1.USDC?.address
        ) && hexStringEquals(toAddress(l2Token), this.messenger.contracts.l2.L2USDC?.address)
      )
    } catch(err) {
      return false
    }
  }
}
